import json,hashlib
from pathlib import Path
D={}
def topic(id,title,goal):D[id]={'title':title,'goal':goal,'cases':[]}
def case(id,name,rule,when,figure,given,steps,trap=''):
 cs={'id':'case-'+str(len(D[id]['cases'])+1),'name':name,'rule':rule,'when':when,'figure':figure,'given':given,'steps':[],'trap':trap}
 for label,equation,why in steps:
  speech=label+'. '+why
  cs['steps'].append({'label':label,'equation':equation,'why':why,'audio':'audio/c1-'+hashlib.sha256(speech.encode()).hexdigest()[:14]+'.mp3'})
 D[id]['cases'].append(cs)
topic('1.1','Recognize the circuit','Identify the purpose, the parts, and the ideal model.')
case('1.1','Source, link, load','Identify each part by what it does.','When naming the parts of a physical circuit.','lamp','A battery, switch, wires and lamp.', [('Find the source','Battery → source','The battery supplies electrical energy.'),('Follow the connection','Switch + wires → intermediate link','The switch and conductors connect the source to the load.'),('Find the useful output','Lamp → load','The lamp converts electrical energy into light and heat.')])
case('1.1','Power or signal?','Classify by the circuit’s main purpose.','When the question asks for the circuit type.','blocks','Compare a torch with a microphone–amplifier–speaker system.', [('Power circuit','Battery → lamp → light','The main purpose is to deliver and convert energy.'),('Signal circuit','Microphone → amplifier → speaker','The main purpose is to transmit or process information.'),('Check the purpose','Energy delivery ≠ information processing','Both kinds use energy; energy consumption alone does not identify the type.')])
case('1.1','Physical or ideal?','A circuit model replaces real parts with ideal elements.','When moving from a physical device to a schematic.','lamp','Model the battery, lamp and switch.', [('Replace the real parts','Battery → ideal source; lamp → load','The model keeps the electrical relationships needed for the problem.'),('Check the connection','Closed switch → complete path','An open switch interrupts the path; a closed switch completes it.'),('Recognize the network','Two terminals; active or passive','In this course’s introductory classification, an active network contains a source; a passive one contains no source.')])
case('1.1','More load','At fixed supply voltage, more consumed power requires more current.','When the course says “load increases.”','load-change','A 10 V source feeds one 2 Ω resistor, then two in parallel.', [('One load','I = 10 / 2 = 5 A','The first resistor takes five amperes.'),('Add another parallel load','I = 5 + 5 = 10 A','The voltage stays ten volts while total current increases.'),('Interpret “more load”','P = UI: 50 W → 100 W','More load does not generally mean more equivalent resistance.')])
topic('1.2','Use the right quantity','Keep voltage, current, power, energy and their units separate.')
case('1.2','Power','P = UI for the DC load in this example.','When asked for the rate of energy use.','power','A bulb takes 1.6 A at 6 V.', [('Read the two quantities','U = 6 V; I = 1.6 A','Use voltage and current, not the duration.'),('Multiply','P = 6 × 1.6','Volts times amperes gives watts.'),('State the answer','P = 9.6 W','Power describes how fast energy is transferred.')])
case('1.2','Energy','W = Pt when power is constant.','When asked how much energy is used over a duration.','energy','A bulb takes 10 mA at 2 V for 30 minutes.', [('Convert the units','I = 0.010 A; t = 1800 s','Convert milliamperes and minutes before substituting.'),('Find constant power','P = 2 × 0.010 = 0.020 W','The source supplies twenty milliwatts to the load.'),('Include the time','W = 0.020 × 1800 = 36 J','Energy depends on duration. One kilowatt-hour equals 3.6 million joules.')], 'kW measures power; kWh measures energy.')
case('1.2','Node potential','Uₐᵦ = Vₐ − Vᵦ.','When voltage is given through node potentials.','ground-two','10 V across two equal 2 Ω resistors.', [('Set the reference','V꜀ = 0; Vₐ = 10 V; Vᵦ = 5 V','A node potential needs a chosen zero.'),('Subtract the potentials','Uₐᵦ = 10 − 5 = 5 V','Voltage is the difference between two node potentials.'),('Move the reference','Vₐ = 0; Vᵦ = −5 V; V꜀ = −10 V','The node numbers shift, but each resistor still has a five volt drop.')])
case('1.2','Current','Current is how much charge crosses a point each second.','For steady flow, use I = Q / t.','charge','A total of 6 C crosses the marked section of a wire in 3 s.', [('Count charge through one section','Q = 6 C','Imagine a counting line across the wire. Count the charge that crosses it, not the charge sitting in the wire. C means coulomb, the unit of charge.'),('Measure the time','I = Q / t = 6 / 3','Those six coulombs cross in three seconds. Divide the total charge by the time to find the charge passing each second.'),('Read the meaning of amperes','I = 2 C/s = 2 A','Two amperes means two coulombs cross that section every second. The arrow shows conventional positive-charge flow; electrons in a metal drift the other way.')], 'Current is a flow rate, not the speed of an individual electron. If the flow varies, Q / t gives average current; instantaneous current is i = dq/dt.')
case('1.2','EMF or terminal voltage?','While the battery supplies current: U = E − IR₀.','Current leaves the positive terminal; E is the source EMF (also written Uₛ).','emf-terminal','A real battery has E = 12 V and R₀ = 2 Ω, connected to a 4 Ω load.', [('What EMF means','E = 12 V → 12 J supplied per coulomb','EMF means electromotive force, but it is not a mechanical force. It is the energy the source supplies per coulomb. Here the battery converts chemical energy into twelve joules of electrical energy for each coulomb.'),('Why the output is lower','I = 12 / (2 + 4) = 2 A; IR₀ = 4 V','A real battery also has internal resistance. At two amperes, its two ohms causes a four volt internal drop: four joules per coulomb becomes heat inside the battery.'),('What terminal voltage means','U = 12 − 4 = 8 V; no current → U = E = 12 V','Terminal voltage is the potential difference measured across the battery output terminals a and b. Here it is eight volts, so the external load receives eight joules per coulomb. With the load disconnected, current and the internal drop are zero in this model.')], 'For this supplying battery: 12 J/C supplied = 4 J/C dissipated inside + 8 J/C delivered outside. During charging the current reverses, so the terminal voltage can exceed the EMF.')
topic('1.3','Open, short or loaded?','Recognize the condition before choosing the equation.')
case('1.3','Loaded','I = Uₛ / (R₀ + R).','A practical voltage source supplies a finite resistive load.','loaded','Uₛ = 12 V; R₀ = 2 Ω; R = 4 Ω.', [('Add the resistances','Rtotal = 2 + 4 = 6 Ω','The same current goes through the internal and load resistances.'),('Calculate current','I = 12 / 6 = 2 A','Use the whole series resistance.'),('Find terminal voltage','U = IR = 2 × 4 = 8 V','The load gets eight volts; four volts is lost internally.')])
case('1.3','Open circuit','An open branch has zero current.','The external terminals are disconnected.','open','The same 12 V source has no connected load.', [('Break the path','I = 0 A','No current flows through the open external path.'),('Check the internal drop','IR₀ = 0 V','With no current, the internal resistor drops no voltage.'),('Read the terminals','Uopen = 12 V; Pload = 0 W','An open circuit can have nonzero voltage.')], 'Open circuit means zero current, not necessarily zero voltage.')
case('1.3','Short circuit','A short has zero terminal voltage.','The source model has nonzero internal resistance.','short','Uₛ = 12 V; R₀ = 2 Ω; the external terminals are shorted.', [('Set the load resistance to zero','R = 0 Ω; U = 0 V','The short connects the output terminals directly.'),('Keep internal resistance','Ishort = 12 / 2 = 6 A','The internal resistance limits current in this model.'),('Check the loss','Pinternal = 6² × 2 = 72 W','Zero terminal power does not mean zero internal heating.')], 'Do not assign a finite current to a shorted ideal zero-resistance voltage source.')
case('1.3','Power balance','Generated power = delivered power + internal loss.','When the source has an internal voltage drop.','source-balance','Teacher example: Uₛ = 125 V, U = 115 V, I = 4 A.', [('Generated and delivered','Pₛ = 500 W; Pload = 460 W','Multiply each relevant voltage by the same current.'),('Find the internal resistance','R₀ = (125 − 115) / 4 = 2.5 Ω','The missing ten volts is the internal resistor drop.'),('Verify the balance','Ploss = 40 W = I²R₀','Five hundred watts supplied equals four hundred sixty delivered plus forty lost.')])
topic('1.4','Get the signs right','Choose references once, then let the answer’s sign tell you the direction.')
case('1.4','Change the ground','Changing ground changes potentials, not voltage differences.','When a reference node is specified or moved.','ground-three','10 V source; 4 Ω, 3 Ω and 3 Ω in series.', [('Use the bottom node as zero','I = 1 A; Vₐ = 10; Vᵦ = 6; V꜀ = 3 V','The series drops are four, three and three volts.'),('Use the top node as zero','Vₐ = 0; Vᵦ = −4; V꜀ = −7; Vd = −10 V','Subtract ten volts from every potential.'),('Check one unchanged difference','Uₐᵦ = 4 V in both choices','Circuit ground is a chosen reference; it need not be physical earth.')])
case('1.4','Reverse voltage polarity','Uᵦₐ = −Uₐᵦ.','When the order of voltage subscripts or polarity marks changes.','polarity','A 5 Ω resistor has 2 A flowing from a to b.', [('Use a as the positive reference','Uₐᵦ = 5 × 2 = 10 V','The current enters the positive terminal.'),('Swap the voltage reference','Uᵦₐ = −10 V','Swapping the ordered terminals reverses the voltage sign.'),('Keep the physical circuit','The resistor and current did not change','Only the measurement reference changed.')])
case('1.4','Negative current','A negative result means flow opposite to the chosen arrow.','When your solved current has a minus sign.','negative-current','10 V across a 5 Ω resistor; choose the current arrow upward.', [('Keep the chosen arrow','U = −RI','The chosen current enters the resistor’s negative terminal.'),('Solve with that reference','I = −10 / 5 = −2 A','The minus sign belongs to the chosen reference.'),('Interpret the result','Actual current: 2 A downward','Do not silently flip the arrow halfway through the calculation.')])
case('1.4','Midpoint potential','Equal series resistors split the potential difference equally.','The midpoint is unloaded.','midpoint','Two equal resistors lie between +12 V and −10 V.', [('Find the full difference','12 − (−10) = 22 V','The endpoints are twenty-two volts apart.'),('Split it equally','22 / 2 = 11 V','Each equal resistor drops eleven volts.'),('Use the stated reference','Vmid = −10 + 11 = 1 V','The midpoint is one volt, not eleven volts.')])
topic('1.5','Elements and ideal sources','Know which quantity an element or source fixes.')
case('1.5','Resistor','u = Ri with passive references.','Current enters the terminal marked positive.','resistor-law','R = 8 Ω; u = 16 V.', [('Choose the reference','u = Ri','Keep the voltage and current references consistent.'),('Find the current','i = 16 / 8 = 2 A','Divide voltage by resistance.'),('Check absorbed power','P = ui = 32 W','A positive ideal resistor dissipates nonnegative power.')])
case('1.5','Capacitor','iC = C · duC/dt.','Use the capacitor’s voltage slope, with passive references.','capacitor-law','C = 10 µF; voltage rises by 2 V in 10 ms.', [('Find the slope','duC/dt = 2 / 0.010 = 200 V/s','Use the rate of change, not the voltage alone.'),('Multiply by capacitance','iC = 10 × 10⁻⁶ × 200 = 2 mA','A constant voltage gives zero ideal capacitor current.'),('Recognize stored energy','WC = ½CuC²; at 2 V, WC = 20 µJ','A capacitor stores electrical energy; it does not store current.')])
case('1.5','Inductor','uL = L · diL/dt.','Use the inductor’s current slope, with passive references.','inductor-law','L = 0.5 H; current rises by 2 A in 0.5 s.', [('Find the current slope','diL/dt = 2 / 0.5 = 4 A/s','Use the change in current per second.'),('Multiply by inductance','uL = 0.5 × 4 = 2 V','Constant ideal inductor current gives zero voltage.'),('Recognize stored energy','WL = ½LiL²; at 2 A, WL = 1 J','The induced EMF opposes the change; in the course convention uL = −e.')])
case('1.5','Ideal voltage source','An ideal voltage source fixes voltage, not current.','When the source is explicitly ideal.','load-change','10 V source; start with one 2 Ω load.', [('One branch','I = 10 / 2 = 5 A','The connected resistance determines current.'),('Add an equal parallel branch','Isource = 5 + 5 = 10 A','The source still imposes ten volts.'),('Keep the distinction','Voltage fixed; current changes','Do not assume an ideal voltage source fixes both voltage and current.')])
case('1.5','Ideal current source','An ideal current source fixes current, not voltage.','When the source is explicitly ideal.','current-source','A 1 A source feeds a resistive load.', [('Use a 1 Ω load','U = 1 × 1 = 1 V','The load determines the required source voltage.'),('Change to 10 Ω','U = 1 × 10 = 10 V','The source current stays at one ampere.'),('Keep the distinction','Current fixed; voltage changes','The source imposes current while the connected circuit determines voltage.')])
case('1.5','Absorb or supply?','pabs = ui when current enters the positive terminal.','When deciding whether a device absorbs or delivers power.','source-absorbs','A 3 V source receives 3 A into its positive terminal.', [('Read the actual direction','Current enters +','The word source does not decide the power sign.'),('Calculate absorbed power','pabs = 3 × 3 = +9 W','Positive absorbed power means the device takes in energy.'),('Check the other source','The 3 A source supplies 9 W','The power balance still holds. All five teacher power cases are available in the full lesson below.')])
topic('1.6','Change the source form','Simplify the external network without changing what the load sees.')
case('1.6','Voltage → current','Is = Us / R; series R becomes parallel R.','A finite, nonzero series resistance accompanies the voltage source.','transform','10 V in series with 2 Ω; a 3 Ω load.', [('Start with the voltage form','IL = 10 / (2 + 3) = 2 A','The load and source resistance are in series.'),('Transform the source','Is = 10 / 2 = 5 A','Keep two ohms, but put it in parallel. The current arrow points toward the original positive terminal.'),('Check the load','IL = 5 × 2 / (2 + 3) = 2 A','Both forms give the same external load current.')])
case('1.6','Current → voltage','Us = IsR; parallel R becomes series R.','A finite, nonzero parallel resistance accompanies the current source.','transform-reverse','5 A in parallel with 2 Ω; a 3 Ω load.', [('Start with current division','IL = 5 × 2 / 5 = 2 A','The current divides between the internal resistor and the load.'),('Transform the source','Us = 5 × 2 = 10 V','Keep two ohms in series with the voltage source.'),('Check the load','IL = 10 / (2 + 3) = 2 A','Equivalence is at the terminals, not in every internal power value.')])
case('1.6','Combine sources','Transform compatible sources, then combine their currents.','The branches share the same output terminals and polarity.','combine','Teacher example: 40 V + 2 Ω and 20 V + 2 Ω feed a 4 Ω load.', [('Transform both branches','20 A + 10 A = 30 A','The two equivalent source arrows point in the same direction.'),('Combine internal resistors','2 Ω ∥ 2 Ω = 1 Ω','Both source resistances are now in parallel.'),('Divide into the load','IL = 30 × 1 / (1 + 4) = 6 A','The four ohm load has twenty-four volts across it.')])
case('1.6','Simplify an ideal source','Some extra resistors do not change the external load quantity.','A resistor is across an ideal voltage source, or in series with an ideal current source.','irrelevant','Compare what the external load sees.', [('Across an ideal voltage source','Uload = 10 V; Iload = 10 / 5 = 2 A','An added parallel resistor cannot change the imposed voltage.'),('In series with an ideal current source','Iload = 1 A; Uload = 1 × 5 = 5 V','An added series resistor cannot change the imposed current.'),('Keep the boundary clear','External behavior only','The simplification does not preserve the removed resistor’s internal power.')])
topic('1.7','Write the right balance','Use current balance at nodes and voltage balance around loops.')
case('1.7','KCL: a node','Sum of incoming currents = sum of outgoing currents.','Apply consistent current references at a node.','kcl','5 A enters; 2 A and I leave.', [('Read the arrows','5 = 2 + I','Classify currents by the arrows you chose.'),('Solve the unknown','I = 5 − 2 = 3 A','The outgoing current is three amperes.'),('Check the balance','5 − 2 − 3 = 0','Charge does not accumulate at an ideal lumped-circuit node.')])
case('1.7','KVL: a loop','The algebraic sum of loop voltage changes is zero.','Choose one traversal direction and keep every polarity consistent.','kvl','12 V source; 2 Ω and 4 Ω in series.', [('Choose the traversal','+12 − 2I − 4I = 0','The source is a rise and the resistor voltages are drops in this traversal.'),('Solve','I = 12 / 6 = 2 A','The same current goes through both series resistors.'),('Check the drops','12 − 4 − 8 = 0','Reversing traversal reverses every sign, giving an equivalent equation.')])
case('1.7','Count independent equations','Use n − 1 node equations and b − n + 1 loop equations.','For the connected circuit graph used by the course.','branches','Teacher graph: n = 3 essential nodes, b = 5 branches.', [('Count the nodes and branches','n = 3; b = 5','Connected conductors count as one node.'),('Count independent KCL equations','n − 1 = 2','A third node equation would repeat information.'),('Count independent loop equations','b − n + 1 = 3','All possible loops are not the same as an independent loop set. A mesh contains no smaller loop.')])
case('1.7','A whole boundary','KCL also applies to a closed boundary around several elements.','When internal details are not needed for the external current balance.','boundary','2 A and 3 A enter a boundary; one current leaves.', [('Choose the boundary','Iout = I₁ + I₂','Count only currents crossing the boundary.'),('Add the external currents','Iout = 2 + 3 = 5 A','Internal currents cancel when the enclosed node equations are added.'),('Use the same law','Σ Icrossing = 0','KCL and KVL do not require a linear circuit; superposition does.')])
case('1.7','Terminal-voltage signs','Use the current reference to choose Us − RI or Us + RI.','A source and resistor form a two-terminal branch.','terminal','Us = 10 V; R = 2 Ω; the external circuit sets a 2 A current.', [('Current leaves the positive output','U = 10 − 2 × 2 = 6 V','The resistor drop reduces the terminal voltage in this reference.'),('Current enters the positive output','U = 10 + 2 × 2 = 14 V','The current reference reverses the resistor voltage term.'),('Keep one sign convention','U = Us ∓ RI','A generalized loop can include the terminal voltage between two points.')])
topic('1.8','Solve branch currents','Turn one diagram into a complete, independent equation system.')
case('1.8','Assign the arrows','Choose branch-current references before writing equations.','Several unknown branch currents prevent easy reduction.','branches','The teacher’s five-branch graph has symbolic component values.', [('Identify the five unknowns','I₁, I₂, I₃, I₄, I₅','The drawing’s arrows are references, not promises about actual flow.'),('Write the two node equations','I₁ − I₃ − I₅ = 0; I₅ + I₂ − I₄ = 0','Use one independent equation at each of the two top nodes.'),('Avoid a repeated equation','2 independent KCL equations','The bottom-node balance follows from these two equations.')])
case('1.8','Complete the system','Combine independent KCL, KVL and element laws.','Use the same arrows throughout the equation system.','branches','Continue with the teacher’s symbolic five-branch circuit.', [('Left loop','I₃R₃ + I₁R₁ − Us₁ = 0','Use the marked source polarity and current references.'),('Middle and right loops','I₅R₅ + I₄R₄ − I₃R₃ = 0; Us₂ − I₂R₂ − I₄R₄ = 0','These give the other two independent loop equations.'),('Solve the complete system','2 node + 3 loop = 5 equations','The teacher gives symbolic values here, so the intended result is this system, not an invented numerical current.')])
case('1.8','Interpret a negative answer','Keep a negative solution and interpret its direction.','The solved current disagrees with your original arrow.','negative-current','A 10 V resistor drop is paired with an upward current reference through 5 Ω.', [('Use the chosen references','10 = −5I','The chosen current enters the negative voltage terminal.'),('Calculate','I = −2 A','The algebraic answer is negative in that reference.'),('Report the physical direction','2 A downward','Changing the arrow without changing its signed variable makes the equations inconsistent.')])
topic('1.9','Separate the sources','Find each contribution with the same reference, then add the signed results.')
case('1.9','Suppress a voltage source','Set an inactive independent ideal voltage source to zero: a short.','Superposition in a linear circuit; keep resistances.','super-voltage','Teacher example: 18 V + 1 Ω and 9 V + 1 Ω feed a 4 Ω load.', [('Keep the 18 V source','Other voltage source → short','The one ohm resistor in that branch must remain.'),('Find this contribution','Vnode = 8 V; IL′ = 8 / 4 = 2 A','The inactive branch still affects the network through its resistance.'),('Keep the reference','IL′ = +2 A downward','Use the same current arrow when solving the other contribution.')])
case('1.9','Suppress a current source','Set an inactive independent ideal current source to zero: an open.','Superposition in a linear circuit; dependent sources stay active.','super-current','With the current-source branch opened, 12 V drives 2 Ω + 4 Ω.', [('Remove only its imposed current','Inactive current source → open','Do not replace a zero-current source by a conducting wire.'),('Solve the remaining path','IL = 12 / (2 + 4) = 2 A','The active voltage source still drives the resistor path.'),('Keep signs and resistors','Contribution: +2 A downward','Preserve resistances and any dependent-source constraints.')])
case('1.9','Add the contributions','Add currents or voltages algebraically.','Each source contribution uses the same target and reference.','super-add','Use the same 18 V / 9 V teacher example.', [('First source alone','IL′ = +2 A','With the nine volt source zeroed, the load-node voltage is eight volts.'),('Second source alone','IL″ = +1 A','With the eighteen volt source zeroed, the load-node voltage is four volts.'),('Add signed answers','IL = 2 + 1 = 3 A','The combined node voltage is twelve volts. If a contribution were negative, you would subtract it.')])
case('1.9','Power is different','Calculate power from the total current or voltage.','Do not superpose powers in a resistor.','power-warning','R = 4 Ω; current contributions +2 A and −1 A.', [('Add current first','I = 2 − 1 = 1 A','Current is a linear response; keep the signs.'),('Calculate the actual power','P = I²R = 1² × 4 = 4 W','Use the total current through the resistor.'),('Reject the tempting shortcut','16 + 4 = 20 W is wrong here','Squaring separate contributions omits the cross term in the square of their sum.')])
topic('1.10','Replace the network at the load','Find the two-terminal equivalent, then reconnect only the target load.')
case('1.10','Find the open voltage','Uth = Uoc at the selected load terminals.','Remove only the external load; keep the remaining network intact.','bridge-open','Teacher’s 8 Ω bridge load is removed between a and b.', [('Keep the original sources active','Vₐ = 4 V','The left two ohm divider gives four volts.'),('Find the other node','Vᵦ = −10 V','The right source branch and downward current source set the other terminal potential.'),('Take the ordered difference','Uₐᵦ = 4 − (−10) = 14 V','The load port lies between two non-ground nodes.')])
case('1.10','Find the resistance','Look into the same port with independent sources suppressed.','Voltage sources become shorts; current sources become opens.','bridge-resistance','Use the teacher’s load port with the 8 Ω load still removed.', [('Suppress independent sources','Voltage → short; current → open','Do not remove the surrounding resistors or the shared bottom connection.'),('Reduce the port resistance','Rth = (2 Ω ∥ 2 Ω) + 5 Ω','The two left resistors are parallel; the right five ohms is in series as seen from a to b.'),('Calculate','Rth = 1 + 5 = 6 Ω','If dependent sources are present, a test source may be needed; do not zero dependent sources.')])
case('1.10','Reconnect the load','IL = Uth / (Rth + RL).','The Thévenin source is in series with its resistance and the load.','thevenin','Uth = 14 V; Rth = 6 Ω; RL = 8 Ω.', [('Build the equivalent','14 V in series with 6 Ω and 8 Ω','The equivalent replaces the original network at the same port.'),('Find load current','IL = 14 / (6 + 8) = 1 A','The current flows from a to b for the positive open-circuit voltage reference.'),('Check the load voltage','UL = 1 × 8 = 8 V','The loaded voltage is eight volts, not the fourteen volt open-circuit value.')])
case('1.10','Use Norton instead','IN = Uth / Rth; keep Rth in parallel.','The equivalent port relationship is finite and defined.','norton','Convert the same 14 V, 6 Ω equivalent and keep the 8 Ω load.', [('Convert the source','IN = 14 / 6 = 7/3 A','The same six ohms becomes a parallel resistance.'),('Use current division','IL = (7/3) × 6 / (6 + 8) = 1 A','Use the other branch’s resistance in the numerator.'),('Check agreement','Thévenin and Norton: IL = 1 A','Choose whichever form makes the load calculation simpler.')])
